def solve(rows):
    # Filter rows where outcome is 'completed' or 'no_show'
    completed_rows = [row for row in rows if row['outcome'] in ('completed', 'no_show')]

    # Group by department
    department_data = {}
    for row in completed_rows:
        department = row['department']
        if department in department_data:
            department_data[department] += 1
        else:
            department_data[department] = 1

    # Calculate percentage for each department
    department_percentages = {}
    for department, count in department_data.items():
        total_rows = len(completed_rows)
        percentage = round(100 * count / total_rows, 1)
        department_percentages[department] = percentage

    # Filter percentages >= 30
    filtered_percentages = {dept: perc for dept, perc in department_percentages.items() if perc >= 30}

    # Sort by percentage (descending), then by value (ascending)
    sorted_percentages = sorted(filtered_percentages.items(), key=lambda x: (-x[1], x[0]))

    # Prepare result
    result = []
    for dept, perc in sorted_percentages:
        result.append((dept, perc))

    return result
```

