    completed_rows = [row for row in rows if row['outcome'] == 'completed']

    # Group rows by doctor
    doctor_data = {}
    for row in completed_rows:
        doctor = row['doctor']
        duration = row['duration_min']
        if doctor not in doctor_data:
            doctor_data[doctor] = []
        doctor_data[doctor].append(duration)

    # Calculate median for each doctor
    doctor_medians = {}
    for doctor, durations in doctor_data.items():
        durations.sort()
        n = len(durations)
        mid = n // 2
        if n % 2 == 1:
            median = durations[mid]
        else:
            median = (durations[mid - 1] + durations[mid]) / 2
        doctor_medians[doctor] = round(median, 1)

    return doctor_medians
```

