def solve(rows):
    filtered_rows = [row for row in rows if row['site'] in ['gwangju', 'incheon']]
    if not filtered_rows:
        return None

    site_unit_weight_sum = {}
    for row in filtered_rows:
        site = row['site']
        units = row['units']
        weight_kg = row['weight_kg']
        key = (site, units, weight_kg)
        if key not in site_unit_weight_sum:
            site_unit_weight_sum[key] = 0
        site_unit_weight_sum[key] += 1

    site_total = {}
    for key, count in site_unit_weight_sum.items():
        site = key[0]
        if site not in site_total:
            site_total[site] = 0
        site_total[site] += count * key[1] * key[2]

    max_total = max(site_total.values())
    candidates = [site for site, total in site_total.items() if total == max_total]
    return min(candidates)
```

