            site = row['site']
            site_returned_counts[site] = site_returned_counts.get(site, 0) + 1

    # Calculate the total number of rows for each site
    site_total_counts = {}
    for row in filtered_rows:
        site = row['site']
        site_total_counts[site] = site_total_counts.get(site, 0) + 1

    # Calculate the percentage for each site
    site_percentages = {}
    for site in site_returned_counts:
        total = site_total_counts[site]
        returned = site_returned_counts[site]
        percentage = (returned / total) * 100
        site_percentages[site] = percentage

    # Filter percentages >= 20 and sort by percentage high to low, then by value alphabetically
    sorted_percentages = sorted(
        [(site, round(100 * site_percentages[site], 1)) for site in site_percentages if site_percentages[site] >= 20],
        key=lambda x: (-x[1], x[0])
    )

    # Prepare the result
    result = []
    for site, percentage in sorted_percentages:
        result.append((site, percentage))

    return result
