    filtered_rows = [row for row in rows if row["weight_kg"] < 151]

    # Initialize variables
    balance = 0
    min_balance = 0
    min_day = None

    # Process rows in ascending order of day, then shipment_id
    for row in sorted(filtered_rows, key=lambda x: (x["day"], x["shipment_id"])):
        phase = row["phase"]
        units = row["units"]

        if phase == "held":
            balance += units
        elif phase == "returned":
            balance -= units

        # Update min_balance and min_day if balance is lower
        if balance < min_balance:
            min_balance = balance
            min_day = row["day"]
        elif balance == min_balance:
            # Check if the day is earlier
            if row["day"] < min_day:
                min_day = row["day"]

    # Return the result
    if min_balance != 0:
        return [min_balance, min_day]
    else:
        return [0, None]
