    # Calculate percentages and filter for percentages >= 20
    result = []
    for site in site_held_counts:
        if site in site_total_counts:
            held_count = site_held_counts[site]
            total_count = site_total_counts[site]
            percentage = round(100 * (held_count / total_count), 1)
            if percentage >= 20:
                result.append((percentage, site))

    # Sort by percentage descending, then by site alphabetically
    result.sort(key=lambda x: (-x[0], x[1]))

    # Format the result as a list of [value, percentage] pairs
    formatted_result = [[site, percentage] for percentage, site in result]

