def solve(rows):
    # Group rows by department
    department_groups = {}
    for row in rows:
        department = row["department"]
        if department not in department_groups:
            department_groups[department] = []
        department_groups[department].append(row)

    # Calculate completed visits for each department
    completed_counts = {}
    for department, group in department_groups.items():
        completed_counts[department] = sum(1 for row in group if row["outcome"] == "completed")

    # Calculate total visits for each department
    total_counts = {}
    for department, group in department_groups.items():
        total_counts[department] = len(group)

    # Calculate percentages for departments with completed visits
    percentage_values = []
    for department, count in completed_counts.items():
        if total_counts[department] == 0:
            continue
        percentage = round(100 * count / total_counts[department], 1)
        if percentage >= 35:
            percentage_values.append((percentage, department))

    # Sort by percentage (descending) and then by department (alphabetically)
    sorted_percentage_values = sorted(percentage_values, key=lambda x: (-x[0], x[1]))

    # Return the result
    return sorted_percentage_values
```

