    completed_counts = {dept: len(completed) for dept, completed in department_groups.items()}

    # Calculate total rows in each department
    total_rows = {dept: len(completed) for dept, completed in department_groups.items()}

    # Calculate percentage for each department
    percentages = {}
    for dept, completed in completed_counts.items():
        total = total_rows[dept]
        if total == 0:
            percentage = 0.0
        else:
            percentage = (100 * completed) / total
        percentages[dept] = percentage

    # Filter percentages >= 35%
    filtered_percentages = {dept: percent for dept, percent in percentages.items() if percent >= 35}

    # Sort by percentage (descending) and then by value (alphabetically)
    sorted_percentages = sorted(filtered_percentages.items(), key=lambda x: (-x[1], x[0]))

    # Prepare result
    result = []
    for dept, percent in sorted_percentages:
        result.append((dept, percent))

    return result
