def solve(rows):
    # Filter rows where units is 8 or more
    filtered_rows = [row for row in rows if row['units'] >= 8]

    # Calculate total units * weight_kg for each site
    site_totals = {}
    for row in filtered_rows:
        site = row['site']
        units = row['units']
        weight_kg = row['weight_kg']
        total = units * weight_kg
        if site in site_totals:
            site_totals[site] += total
        else:
            site_totals[site] = total

    # Find the site with the highest total, and alphabetically first on tie
    if not site_totals:
        return None

    max_total = max(site_totals.values())
    candidates = [site for site, total in site_totals.items() if total == max_total]
    return min(candidates)
