def solve(rows):
    # Group by carrier and sum units and weight_kg
    grouped = {}
    for row in rows:
        carrier = row["carrier"]
        units = row["units"]
        weight_kg = row["weight_kg"]
        if carrier in grouped:
            grouped[carrier] = {
                "units": grouped[carrier]["units"] + units,
                "weight_kg": grouped[carrier]["weight_kg"] + weight_kg
            }
        else:
            grouped[carrier] = {
                "units": units,
                "weight_kg": weight_kg
            }

    # Sort carriers by units (descending), then by weight_kg (descending), then by name (ascending)
    sorted_carriers = sorted(grouped.items(), key=lambda x: (-x[1]["units"], -x[1]["weight_kg"], x[0]))

    # Filter to get the top two carriers
    top_two = sorted_carriers[:2]

    # If there are at least two carriers, return the second one; else, return None
    if len(top_two) >= 2:
        return top_two[1][0]
    else:
        return None
