def solve(rows):
    # Initialize variables
    balance = 0
    min_balance = 0
    min_day = None

    # Process each row
    for row in rows:
        outcome = row['outcome']
        if outcome == 'no_show':
            # 'no_show' rows add duration_min
            duration = row['duration_min']
            balance += duration
        elif outcome == 'completed':
            # 'completed' rows subtract duration_min
            duration = row['duration_min']
            balance -= duration
        else:
            # Ignore other outcomes
            pass

        # Update min_balance and min_day
        if balance != 0:
            if min_balance < balance:
                min_balance = balance
                min_day = row['day']
            elif min_balance == balance:
                # If same balance, keep the earliest day
                if min_day is None or row['day'] < min_day:
