    filtered_rows = [row for row in rows if row['day'] <= 15]

    # Group by depot and calculate the sum of (packages * distance_km)
    depot_totals = {}
    for row in filtered_rows:
        depot = row['depot']
        packages = row['packages']
        distance_km = row['distance_km']
        key = (depot, packages, distance_km)
        if depot not in depot_totals:
            depot_totals[depot] = 0
        depot_totals[depot] += packages * distance_km

    # If no rows, return None
    if not depot_totals:
        return None

    # Find the depot with the highest total
    max_total = -1
    best_depot = None
    for depot, total in depot_totals.items():
        if total > max_total:
            max_total = total
            best_depot = depot
        elif total == max_total:
            if depot < best_depot:
                best_depot = depot

    return best_depot
