    grouped = {}
    for row in filtered_rows:
        depot = row['depot']
        if depot not in grouped:
            grouped[depot] = {'on_time': 0, 'total': 0}
        grouped[depot]['total'] += 1
        if row['result'] == 'on_time':
            grouped[depot]['on_time'] += 1

    result = []
    for depot in grouped:
        total = grouped[depot]['total']
        on_time = grouped[depot]['on_time']
        if total == 0:
            percentage = 0.0
        else:
            percentage = round(100 * on_time / total, 1)
        if percentage >= 35:
            result.append((depot, percentage))

    result.sort(key=lambda x: (-x[1], x[0]))
    return result
