        else:
            percentage = round(100 * on_time / total, 1)
        percentages[depot] = percentage

    # Filter percentages >= 35 and sort
    filtered_percentages = {depot: percentage for depot, percentage in percentages.items() if percentage >= 35}
    sorted_percentages = sorted(filtered_percentages.items(), key=lambda x: (-x[1], x[0]))

    # Prepare result
    result = []
    for depot, percentage in sorted_percentages:
        result.append((depot, percentage))

    return result
