def solve(rows):
    filtered_rows = [row for row in rows if row['day'] <= 18]
    if not filtered_rows:
        return 0.0
    total_duration = sum(row['duration_min'] for row in filtered_rows)
    average = total_duration / len(filtered_rows)
    return round(average, 2)
